"""The stub (`__init__.pyi`, generated by `cargo xtask pystub`) and the runtime agree: every
method and function has the same parameters and docstring in both (Task 9, R3)."""

from __future__ import annotations

import ast
import inspect
from pathlib import Path

import pytest

import gloci

STUB = Path(gloci.__file__).with_name("__init__.pyi")
TREE = ast.parse(STUB.read_text())

P = inspect.Parameter
_KIND_NAMES = {
    P.POSITIONAL_ONLY: "positional-only",
    P.POSITIONAL_OR_KEYWORD: "positional-or-keyword",
    P.VAR_POSITIONAL: "var-positional",
    P.KEYWORD_ONLY: "keyword-only",
    P.VAR_KEYWORD: "var-keyword",
}


def stub_params(fn: ast.FunctionDef) -> list[tuple[str, str, bool]]:
    """(name, kind, has a default) of each parameter, as the stub declares them."""
    a = fn.args
    out: list[tuple[str, str, bool]] = []
    pos = [*a.posonlyargs, *a.args]
    defaults = [None] * (len(pos) - len(a.defaults)) + list(a.defaults)
    for i, arg in enumerate(pos):
        kind = P.POSITIONAL_ONLY if i < len(a.posonlyargs) else P.POSITIONAL_OR_KEYWORD
        out.append((arg.arg, _KIND_NAMES[kind], defaults[i] is not None))
    if a.vararg:
        out.append((a.vararg.arg, _KIND_NAMES[P.VAR_POSITIONAL], False))
    for arg, d in zip(a.kwonlyargs, a.kw_defaults):
        out.append((arg.arg, _KIND_NAMES[P.KEYWORD_ONLY], d is not None))
    if a.kwarg:
        out.append((a.kwarg.arg, _KIND_NAMES[P.VAR_KEYWORD], False))
    return out


def runtime_params(fn: object) -> list[tuple[str, str, bool]]:
    sig = inspect.signature(fn)  # type: ignore[arg-type]
    return [
        (p.name, _KIND_NAMES[p.kind], p.default is not P.empty) for p in sig.parameters.values()
    ]


def stub_class(name: str) -> ast.ClassDef:
    for node in TREE.body:
        if isinstance(node, ast.ClassDef) and node.name == name:
            return node
    raise AssertionError(f"no class {name} in the stub")


def stub_methods(cls: str) -> dict[str, ast.FunctionDef]:
    return {n.name: n for n in stub_class(cls).body if isinstance(n, ast.FunctionDef)}


def stub_functions() -> dict[str, ast.FunctionDef]:
    return {n.name: n for n in TREE.body if isinstance(n, ast.FunctionDef)}


def test_runtime_methods_match_stub() -> None:
    methods = stub_methods("Pipeline")
    assert len(methods) > 40, "the step methods are in the stub"
    for name, node in methods.items():
        got = runtime_params(getattr(gloci.Pipeline, name))
        assert got == stub_params(node), f"Pipeline.{name}"
    # No step method is missing from the stub.
    runtime = {
        n
        for n, v in vars(gloci.Pipeline).items()
        if callable(v) and not (n.startswith("_") and not n.startswith("__iter"))
    }
    assert runtime - {"_make"} <= set(methods), sorted(runtime - set(methods))


def test_runtime_functions_match_stub() -> None:
    functions = stub_functions()
    assert {"open", "windows", "random", "vcf_stats", "vcf_extract_matrix", "vcf_compare"} <= set(
        functions
    )
    for name, node in functions.items():
        got = runtime_params(getattr(gloci, name))
        assert got == stub_params(node), f"gloci.{name}"


def test_docstrings_match_stub() -> None:
    for name, node in stub_methods("Pipeline").items():
        want = ast.get_docstring(node)
        got = inspect.getdoc(getattr(gloci.Pipeline, name))
        assert want and got == want, f"Pipeline.{name}"
    for name, node in stub_functions().items():
        want = ast.get_docstring(node)
        got = inspect.getdoc(getattr(gloci, name))
        assert want and got == want, f"gloci.{name}"


def test_stub_names_exist_at_runtime() -> None:
    names = {
        n.name
        for n in TREE.body
        if isinstance(n, (ast.ClassDef, ast.FunctionDef))
    } | {
        t.id
        for n in TREE.body
        if isinstance(n, ast.AnnAssign) and isinstance(t := n.target, ast.Name)
    }
    names |= {  # re-exports: `from .errors import DataError as DataError`
        a.asname
        for n in TREE.body
        if isinstance(n, ast.ImportFrom)
        for a in n.names
        if a.asname == a.name
    }
    public = {n for n in names if not n.startswith("_")} | {"__version__"}
    missing = [n for n in public if not hasattr(gloci, n)]
    assert not missing, missing
    assert set(gloci.__all__) <= public | {"__version__"}


def test_help_works() -> None:
    doc = inspect.getdoc(gloci.Pipeline.intersect) or ""
    assert "Minimum fraction of A covered" in doc
    assert "CLI: gloci intersect" in doc
    assert "Args:" in doc
    vcf = inspect.getdoc(gloci.Pipeline.vcf_filter) or ""
    assert "CLI: gloci vcf filter" in vcf
    assert "CLI: gloci vcf stats" in (inspect.getdoc(gloci.vcf_stats) or "")
    sig = inspect.signature(gloci.Pipeline.intersect)
    assert "min_frac_a" in sig.parameters
    assert "output" not in sig.parameters and "threads" not in sig.parameters
    assert sig.parameters["b"].kind is P.KEYWORD_ONLY
    assert list(inspect.signature(gloci.Pipeline.merge).parameters)[:2] == ["self", "sources"]


def test_stub_rejects_wrong_calls(tmp_path: Path) -> None:
    api = pytest.importorskip("mypy.api")
    src = tmp_path / "bad.py"
    src.write_text(
        "import gloci\n"
        "p = gloci.open('a.bed')\n"
        "p.intersect(b='b.bed', mode='bogus')\n"
        "p.intersect(b='b.bed', not_a_flag=True)\n"
        "p.merge(output='x')\n"
        "p.intersect(b=3.5j)\n"
    )
    out, _, status = api.run(["--strict", "--no-incremental", str(src)])
    assert status == 1
    for line in (3, 4, 5, 6):
        assert f"bad.py:{line}:" in out, out


def test_short_flags_and_aliases_are_parameters() -> None:
    inter = inspect.signature(gloci.Pipeline.intersect).parameters
    assert {"min_frac_a", "f", "min_frac_b", "F", "reciprocal", "r"} <= set(inter)
    assert "alias of min_frac_a" in (inspect.getdoc(gloci.Pipeline.intersect) or "")
    assert inter["b"].default is inspect.Parameter.empty  # no long form, so no alias: required
    assert inter["f"].default is None
    cmp_ = inspect.signature(gloci.vcf_compare).parameters
    assert "sample_map" in cmp_ and "diff_indv_map" in cmp_
    rnd = inspect.signature(gloci.random).parameters
    assert rnd["genome"].default is None and rnd["g"].default is None  # one of them is needed
    # The names that are not identifiers are in the docstring, not the signature.
    cov = inspect.signature(gloci.Pipeline.genomecov).parameters
    assert "5p" not in cov
    assert '**{"5p": True}' in (inspect.getdoc(gloci.Pipeline.genomecov) or "")
    gloci.open([("chr1", 1, 5)]).genomecov(**{"5p": True}, genome="hg38").to_bytes()


def test_only_unreachable_names_are_skipped() -> None:
    # vcf merge's `-0` is the short form of missing_to_ref, which is a parameter: no hint.
    assert "missing_to_ref" in inspect.signature(gloci.Pipeline.vcf_merge).parameters
    assert "Not Python identifiers" not in (inspect.getdoc(gloci.Pipeline.vcf_merge) or "")
    # genomecov's --5p/--3p are switches: the hint passes True.
    doc = inspect.getdoc(gloci.Pipeline.genomecov) or ""
    assert '**{"5p": True}' in doc


def test_every_parameter_resolves_to_the_argument_the_stub_types(tmp_path: Path) -> None:
    from gloci import _native

    specs = {tuple(s["path"]): {a["id"]: a for a in s["args"]} for s in _native.command_specs()}
    sigs = _native.signatures()
    paths = {b["method"]: tuple(b["path"]) for b in _native.bindings()}
    paths.update({f["function"]: tuple(f["path"]) for f in _native.module_functions()})
    funcs = {f["function"]: f for f in _native.module_functions()}
    checked = 0
    for name, sig in sigs.items():
        path = paths[name]
        for k in sig["args"]:
            arg = specs[path][k["id"]]
            value: object = True if not arg["takes_value"] else "1"
            kw = {k["name"]: value}
            if name in funcs and not funcs[name]["source"]:
                words = _native.function_argv(
                    list(path), ["-"] * len(funcs[name]["inputs"]), kw, check=False
                )
            elif name in funcs:
                words = _native.source_argv(list(path), kw, check=False)
            else:
                words = _native.step_argv(list(path), ["-"], kw, check=False)
            flag = (
                f"--{arg['long']}"
                if arg["long"]
                else f"-{arg['short']}" if arg["short"] else None
            )
            names = {f"--{arg['long']}"} if arg["long"] else set()
            names |= {f"--{a}" for a in arg["aliases"]}
            if arg["short"]:
                names.add(f"-{arg['short']}")
            if arg["positional"]:
                assert "1" in words, (name, k["name"], words)
            else:
                assert any(w.split("=")[0] in names for w in words), (name, k, words, flag)
            checked += 1
    assert checked > 900
